class NodeChecks {
 static readonly List<string> Checks=new List<string>();static GameRuntime G;static int fault;
 static void Check(bool pass,string label){if(!pass)throw new Exception(label);Checks.Add(label);}
 static object Call(string name,params object[] args)=>typeof(GameRuntime).GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(G,args);
 static void Start(){G.NewRun(1,CharacterTable.All[0].id);G.State.entrySupply=null;G.State.ownedCards.Clear();G.State.nodeRewards.Clear();G.State.settled.Clear();G.State.Phase="modal";G.State.battleActive=false;G.State.coins=20;G.SaveCurrent();}
 static ChestVisitReceipt Box(string[] ids,string mode="all",int choices=0){var r=G.CurrentNodeReceipt;r.type="chest";r.chestIndex=0;r.chestQueue=new List<ChestVisitReceipt>{new ChestVisitReceipt{kind="small",cardIds=ids.ToList(),claimMode=mode,choiceCount=choices}};return r.chestQueue[0];}
 static ChestVisitReceipt Current=>G.CurrentNodeReceipt.chestQueue[0];
 static void Fill(){int i=0;while(G.UsedSlots()<G.BagCap){G.State.ownedCards.Add(new OwnedCard{uid="fixture-"+i,card=new CardDef{id="fixture-"+i,name="填充"+i,type="武术",rarity="普通"}});i++;if(i>50)throw new Exception("capacity fixture");}}
 static void Fail(){Directory.CreateDirectory(SaveSystem.ProfilePath+".writing");}
 static void Retry(){Directory.Move(SaveSystem.ProfilePath+".writing",SaveSystem.ProfilePath+".fault-"+(fault++));}
 static void Main(){
  string folder=Path.GetFullPath("_planning/migration-1029/current-node-rooms/domain-check/profile-"+DateTime.UtcNow.ToString("yyyyMMddHHmmssfff"));Directory.CreateDirectory(folder);Environment.SetEnvironmentVariable("SDT_UNITY_TEST_DATA",folder);
  CardLibrary.Init(()=>CardDatabase.All);G=GameRuntime.I;
  var source=JObject.Parse(File.ReadAllText("_planning/migration-1029/current-node-rooms/source-data.json"));
  foreach(var row in source["rewardVectors"]){int n=(int)row["n"];var taken=new HashSet<int>(row["taken"].Values<int>());var lost=new HashSet<int>(row["lost"].Values<int>());for(int i=0;i<n;i++){Check(CurrentRewardState.CardState(taken,lost,i)==(string)row["states"][i],"source reward state "+Checks.Count);Check(CurrentRewardState.Status(CurrentRewardState.CardState(taken,lost,i),true)==(string)row["status"][i],"source reward status "+Checks.Count);}Check(CurrentRewardState.Summary(taken.Count,lost.Count,n,taken.Count+lost.Count==n,true,"任选1张")== (string)row["summary"],"source reward summary "+Checks.Count);}
  foreach(var row in source["optionVectors"]){var c=row["choice"];var actual=CurrentEventOptionState.Read((int)row["hp"],(int)row["coins"],(int)c["healthCost"],(int)c["coinCost"],(string)c["costTiming"]=="entry");Check(JToken.DeepEquals(JToken.FromObject(actual),row["expected"]),"source option warning "+Checks.Count);}
  foreach(string mode in new[]{"standard","elite"})foreach(int n in new[]{0,1,2,4}){
   Start();G.State.mode=mode;var r=G.CurrentNodeReceipt;r.type="coin";int coins=G.State.coins;
   var node=(NodeResult)Call("RunInstant",new GameRuntime.LogicalCell{type="coin",n=n});int value=Math.Max(1,(n>0?n:1)-1);int shown=Math.Max(1,(int)Math.Floor(value*(mode=="elite"?1.5:1)+.5));
   Check(r.pickupPrepared&&!r.pickupClaimed&&G.State.coins==coins&&r.coins==value&&node.Instant.GainText=="+"+shown+" 币","coin defers grant until claim "+mode+":"+n);
   Check(G.TryClaimCurrentPickup(G.CurrentNodeId,out _)&&G.State.coins==coins+shown,"coin claims exact current source amount "+mode+":"+n);
   Check(G.TryClaimCurrentPickup(G.CurrentNodeId,out _)&&G.State.coins==coins+shown,"coin repeated claim is save-only "+mode+":"+n);
  }
  Start();G.CurrentNodeReceipt.type="coin";Call("RunInstant",new GameRuntime.LogicalCell{type="coin",n=4});string disk=File.ReadAllText(SaveSystem.ProfilePath);int before=G.State.coins;Fail();
  Check(!G.TryClaimCurrentPickup(G.CurrentNodeId,out _)&&G.CurrentNodeReceipt.pickupClaimed&&!G.CurrentNodeReceipt.pickupSaved&&G.State.coins==before+3,"coin source checkpoint failure retains one memory claim");Check(File.ReadAllText(SaveSystem.ProfilePath)==disk,"coin failed checkpoint retains disk bytes");Retry();Check(G.TryClaimCurrentPickup(G.CurrentNodeId,out _)&&G.State.coins==before+3&&G.CurrentNodeReceipt.pickupSaved,"coin retry saves without granting again");Check(new SaveSystem().ReadSlot(1).coins==before+3,"coin successful retry reloads one credit");
  Start();G.CurrentNodeReceipt.type="coin";Call("RunInstant",new GameRuntime.LogicalCell{type="coin",n=4});before=G.State.coins;Check(G.TryLeaveCurrentPickup(G.CurrentNodeId,out _)&&!G.CurrentNodeReceipt.pickupClaimed&&G.State.coins==before,"coin unclaimed return leaves reward available");
  foreach(string kind in new[]{"wood","rations","key"}){Start();G.CurrentNodeReceipt.type=kind;Call("RunInstant",new GameRuntime.LogicalCell{type=kind,n=3});var box=Current;Check(G.State.inventory.Count==0&&G.State.ownedCards.Count==0&&box.cardIds.Count==(kind=="wood"?3:1)&&box.cardIds.All(id=>id=="tt-"+kind),"fixed "+kind+" prepares card rewards without inventory credit");Call("RunInstant",new GameRuntime.LogicalCell{type=kind,n=3});Check(Current==box,"fixed "+kind+" reopening reuses receipt");}
  Start();Box(new[]{"starter-attack","tt3-fireball","tt-wood","tt-key"},"one",3);before=G.State.ownedCards.Count;
  Check(!G.TryClaimCurrentChest("wrong",G.State.seed,0,out _)&&!G.TryClaimCurrentChest(G.CurrentNodeId,G.State.seed+1,0,out _),"stale node/seed chest claims rejected");
  Check(G.TryClaimCurrentChest(G.CurrentNodeId,G.State.seed,0,out _)&&G.State.ownedCards.Count==before+1&&Current.taken.SetEquals(new[]{0})&&Current.lost.SetEquals(new[]{1,2})&&!Current.completed,"choice receipt forfeits only other base candidates");
  Check(!G.TryClaimCurrentChest(G.CurrentNodeId,G.State.seed,1,out _)&&G.State.ownedCards.Count==before+1,"lost choice cannot be granted");
  Check(G.TryClaimCurrentChest(G.CurrentNodeId,G.State.seed,3,out _)&&Current.completed&&Current.taken.SetEquals(new[]{0,3}),"bonus remains independently claimable after base choice");
  var reloaded=new SaveSystem().ReadSlot(1).nodeRewards[G.CurrentNodeId].chestQueue[0];Check(reloaded.taken.SetEquals(new[]{0,3})&&reloaded.lost.SetEquals(new[]{1,2}),"taken/lost save roundtrip");
  Start();Box(new[]{"starter-attack","tt3-fireball","tt-key"},"one",3);G.SaveCurrent();disk=File.ReadAllText(SaveSystem.ProfilePath);before=G.State.ownedCards.Count;Fail();Check(!G.TryClaimCurrentChest(G.CurrentNodeId,G.State.seed,0,out _)&&Current.taken.Count==0&&Current.lost.Count==0&&G.State.ownedCards.Count==before,"choice failed save rolls back grant and lost together");Check(File.ReadAllText(SaveSystem.ProfilePath)==disk,"choice failure preserves disk");Retry();Check(G.TryClaimCurrentChest(G.CurrentNodeId,G.State.seed,0,out _)&&Current.lost.Count==2,"choice retry commits once");
  Start();Box(new[]{"starter-attack","tt-wood"});G.State.ownedCards.Add(new OwnedCard{uid="wood",card=CardLibrary.FindById("tt-wood")});Fill();before=G.State.ownedCards.Count;Check(G.TryClaimCurrentChest(G.CurrentNodeId,G.State.seed,-1,out var capacity)&&!string.IsNullOrEmpty(capacity)&&Current.taken.SetEquals(new[]{1})&&Current.lost.Count==0&&G.State.ownedCards.Count==before+1,"bulk skips full candidate and still claims later stackable reward");
  Start();Box(new[]{"starter-attack","tt-key"});G.SaveCurrent();Fail();Check(!G.TryForfeitCurrentChest(G.CurrentNodeId,G.State.seed,out _)&&Current.lost.Count==0&&!Current.completed,"failed forfeit keeps pending cards");Retry();Check(G.TryForfeitCurrentChest(G.CurrentNodeId,G.State.seed,out _)&&Current.lost.SetEquals(new[]{0,1})&&Current.completed,"confirmed forfeit persists all remaining once");
  Start();var money=Box(new[]{"starter-attack"});money.coins=3;before=G.State.coins;Check(G.TryCollectCurrentChestCoins(G.CurrentNodeId,G.State.seed,out _)&&G.TryCollectCurrentChestCoins(G.CurrentNodeId,G.State.seed,out _)&&G.State.coins==before+3,"standard chest coin credit once on presentation");
  Start();Box(new[]{"tt2-apollo"});G.SaveCurrent();string rng=G.Rng.SaveState();Fail();Check(!G.TryClaimCurrentChest(G.CurrentNodeId,G.State.seed,0,out _)&&Current.cardIds.Count==1&&Current.taken.Count==0&&G.Rng.SaveState()==rng,"gift failed save rolls back base, deferred extra and RNG");Retry();Check(G.TryClaimCurrentChest(G.CurrentNodeId,G.State.seed,0,out _)&&Current.cardIds.Count==2&&Current.taken.Contains(0)&&!Current.taken.Contains(1)&&Current.cardIds[1]!="tt2-apollo"&&!Current.completed,"gift extra is drawn once into same pending box");int count=Current.cardIds.Count;Check(!G.TryClaimCurrentChest(G.CurrentNodeId,G.State.seed,0,out _)&&Current.cardIds.Count==count,"gift duplicate cannot reroll extra");
  foreach(string id in new[]{"ev19-potions","ev19-quartermaster"}){
   Start();G.CurrentNodeReceipt.type="event";G.GetEventChoices(id);var layers=EventDatabase.Find(id).Items("layers");var specs=(layers[0] as object[]).OfType<RuleValue>();string route=id.EndsWith("potions")?"potions":"quartermaster";var spec=specs.First(x=>x.Operations("operations").Any(op=>op.Text("op")=="route"&&op.Text("kind")==route));before=G.State.coins;
   var outcome=G.ApplyCurrentEventChoice(spec.Text("key"));Check(outcome.Stage=="dice","actual "+route+" retains real dice entry");int rolls=0;
   while(outcome.Stage=="dice"&&rolls++<6){outcome=G.RollCurrentEventDice();int? result=G.CurrentNodeReceipt.eventProgress.dice[G.CurrentNodeReceipt.eventProgress.diceIndex].result;outcome=G.RollCurrentEventDice();Check(result==G.CurrentNodeReceipt.eventProgress.dice[G.CurrentNodeReceipt.eventProgress.diceIndex].result,"saved "+route+" die does not reroll");outcome=G.ApplyCurrentEventChoice("__dice_continue");}
   Check(outcome.Stage=="selection"&&outcome.CardIds.Count==3&&outcome.CardIds.Distinct().Count()==3&&G.State.coins==before-(route=="quartermaster"?3:0),"three saved "+route+" dice feed reward scene and one payment");
   var candidates=string.Join(",",outcome.CardIds);G.ApplyCurrentEventChoice("__leave");G.GetEventChoices(id);Check(string.Join(",",G.GetCurrentEventOutcome().CardIds)==candidates&&G.State.coins==before-(route=="quartermaster"?3:0),"reentry reuses "+route+" candidates/payment");
  }
  Start();G.CurrentNodeReceipt.type="event";G.GetEventChoices("ev19-quartermaster");var progress=G.CurrentNodeReceipt.eventProgress;progress.stage="selection";progress.route="quartermaster";progress.cardIds=new List<string>{"tt2-apollo"};progress.cardKeys=new List<string>{"0"};progress.need=1;Fill();before=G.State.ownedCards.Count;var gift=G.SubmitEventSelection(new List<string>{"0"});Check(gift.Chests?.Count==1&&G.State.ownedCards.Count==before&&Current.cardIds.SequenceEqual(new[]{"tt2-apollo"})&&Current.taken.Count==0,"quartermaster gift adopts fixed reward despite full bag, no premature grant");
  Start();G.CurrentNodeReceipt.type="event";G.GetEventChoices("ev19-fireballs");var fixedFire=G.ApplyCurrentEventChoice("ev19-fireballs:0");Check(fixedFire.Chests?.Count==1&&Current.cardIds.SequenceEqual(new[]{"tt3-fireball","tt3-fireball"})&&Current.claimMode=="all"&&G.State.ownedCards.Count==0,"source two-fireball event opens fixed all-claim reward, no second selection");
  Check(G.TryClaimCurrentChest(G.CurrentNodeId,G.State.seed,0,out _)&&Current.taken.SetEquals(new[]{0})&&Current.lost.Count==0&&!Current.completed,"source fixed two fireballs remain independently claimable");
  Start();G.CurrentNodeReceipt.type="event";G.GetEventChoices("ev19-fireballs");G.State.hp=Math.Max(1,G.State.maxHp-5);int hpBefore=G.State.hp;var directFire=G.ApplyCurrentEventChoice("ev19-fireballs:1");Check(directFire.Settled&&G.State.ownedCards.Count==1&&G.State.ownedCards[0].card.id=="tt3-fireball"&&G.State.hp==hpBefore+3&&G.CurrentNodeReceipt.chestQueue==null,"capacity fireball branch grants on confirmation with heal, no reward page");
  Start();G.CurrentNodeReceipt.type="event";G.GetEventChoices("ev19-fireballs");G.State.hp=Math.Max(1,G.State.maxHp-5);hpBefore=G.State.hp;Fill();before=G.State.ownedCards.Count;var fullFire=G.ApplyCurrentEventChoice("ev19-fireballs:1");Check(!fullFire.Settled&&G.State.hp==hpBefore&&G.State.ownedCards.Count==before&&G.GetCurrentEventOutcome().Stage=="choices","capacity fireball full bag preserves option and healing");
  Start();G.CurrentNodeReceipt.type="event";G.GetEventChoices("tt6-systemsupply");int fragments=G.State.fragments;G.SaveCurrent();Fail();var failedSupply=G.ApplyCurrentEventChoice("tt6-systemsupply:0");Check(!failedSupply.Settled&&G.State.fragments==fragments&&G.State.ownedCards.Count==0,"capacity supply failed save restores card and fragment together");Retry();var acceptedSupply=G.ApplyCurrentEventChoice("tt6-systemsupply:0");Check(acceptedSupply.Settled&&G.State.fragments==fragments+1&&G.State.ownedCards.Single().card.id=="tt-wood","capacity supply retry commits once");
  Start();var continuation=Box(new[]{"tt-key"});continuation.taken.Add(0);continuation.completed=true;G.CurrentNodeReceipt.battleWon=true;Check(G.TryPrepareCurrentRewardContinuation(G.CurrentNodeId,G.State.seed,out _)&&!G.CurrentNodeReceipt.completed&&!G.State.settled.Contains(G.CurrentNodeId)&&G.State.Phase=="modal","battle room queue completion leaves final node and extra rewards to BattleBridge");
  Start();continuation=Box(new[]{"tt-key"});continuation.taken.Add(0);continuation.completed=true;Check(G.TryPrepareCurrentRewardContinuation(G.CurrentNodeId,G.State.seed,out _)&&G.CurrentNodeReceipt.completed&&G.State.settled.Contains(G.CurrentNodeId)&&G.State.Phase=="idle","ordinary room completion settles node after its queue");
  Start();continuation=Box(new[]{"tt-key"});Check(!G.TryPrepareCurrentRewardContinuation(G.CurrentNodeId,G.State.seed,out _)&&!G.CurrentNodeReceipt.completed,"unresolved queue cannot continue");
  Start();continuation=Box(new[]{"starter-attack","tt3-fireball","tt-key"},"one",3);continuation.taken.Add(0);continuation.completed=true;Check(G.CurrentChestReceipt.lost.SetEquals(new[]{1,2})&&!G.TryClaimCurrentChest(G.CurrentNodeId,G.State.seed,1,out _),"legacy choice receipt normalizes implicit discarded candidates and cannot grant a second base card");
  var legacy=JsonConvert.DeserializeObject<ChestVisitReceipt>("{\"kind\":\"small\",\"cardIds\":[\"tt-key\"],\"taken\":[0]}");Check(legacy.lost!=null&&legacy.lost.Count==0&&legacy.taken.Contains(0),"legacy receipt initializes missing lost set");
  File.WriteAllText("_planning/migration-1029/current-node-rooms/domain-results.json",JsonConvert.SerializeObject(new{passed=true,count=Checks.Count,checks=Checks},Formatting.Indented));Console.WriteLine("Current node source/domain checks: "+Checks.Count+" passed");
 }
